"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["36000"],{28130(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.processo_seletivo.exigencia_menos_protegida_que_fato_comprovado","status":422,"titulo":"O tipo de documento da exig\xeancia \xe9 menos protegido que um fato que ela comprova"},"descricao":{"codigo":"uniplus.selecao.processo_seletivo.exigencia_menos_protegida_que_fato_comprovado","requisitos":["UNI-REQ-0183","UNI-REQ-0071"],"oQueAconteceu":["Uma exig\xeancia de documento do processo declara que o documento comprova um fato\\ndo candidato, mas o tipo de documento escolhido \xe9 menos protegido que esse fato.\\nA publica\xe7\xe3o, ou a retifica\xe7\xe3o, foi recusada. A mensagem cita a exig\xeancia, o tipo\\nde documento e o fato.","Por exemplo: o fato \\"tipo de defici\xeancia\\" \xe9 sens\xedvel. Se a exig\xeancia pede um\\ndocumento cadastrado como pessoal para comprov\xe1-lo, o arquivo que o candidato\\nenviar ficaria menos protegido que a pr\xf3pria informa\xe7\xe3o sobre a defici\xeancia.","Quando a exig\xeancia comprova v\xe1rios fatos, a compara\xe7\xe3o \xe9 feita com o mais\\nprotegido deles. O fato que s\xf3 aciona a exig\xeancia, como a modalidade de\\nconcorr\xeancia, n\xe3o entra na compara\xe7\xe3o: ele decide se o documento \xe9 pedido, mas o\\ndocumento n\xe3o o comprova."],"comoResolver":["Escolha uma destas sa\xeddas:","- troque, na exig\xeancia, o tipo de documento por um tipo t\xe3o protegido quanto o\\n  fato que ele comprova (por exemplo, um laudo cadastrado como sens\xedvel);\\n- se o documento n\xe3o comprova de fato aquele dado, retire o fato da lista de fatos\\n  comprovados pela exig\xeancia.","Se o tipo de documento est\xe1 classificado abaixo do que deveria, corrija a\\nclassifica\xe7\xe3o no cadastro de tipos de documento do m\xf3dulo Configura\xe7\xe3o. A\\ncorre\xe7\xe3o vale para os processos publicados a partir da\xed; os processos j\xe1\\npublicados mant\xeam a classifica\xe7\xe3o congelada na publica\xe7\xe3o."],"ondeAparece":["Publica\xe7\xe3o do processo seletivo","Retifica\xe7\xe3o do processo seletivo"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Processo seletivo"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"137e6bdd986deaebbd7281a2e43c40e18a247a98"}}')}}]);